/* KITchen project page: explorer, object library and statistics.
 * Data comes from data/stats.json, data/explorer_frames.json and static/models/models.json,
 * all generated by the scripts in scripts/. */
(() => {
  'use strict';

  const CATS = ['Packaged food', 'Drinks', 'YCB objects', 'Kitchenware', 'Cups'];
  const fmt = n => n == null ? '–' : n.toLocaleString('en-US');
  const compact = n => n >= 1e6 ? (n / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'M' : n >= 1e4 ? Math.round(n / 1e3) + 'k' : fmt(n);
  const css = name => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  const catColor = c => { const i = CATS.indexOf(c); return css(i >= 0 ? `--s${i + 1}` : '--text-3'); };
  const pad6 = n => String(n).padStart(6, '0');
  // Benchmark splits (kitchenbench): name and colour token per subset.
  const SPLITS = { train: ['Train', '--s1'], val: ['Validation', '--s4'], test: ['Test', '--s5'], buffer: ['Unassigned', '--text-3'] };
  const splitName = f => f.split && SPLITS[f.split] ? `${SPLITS[f.split][0]} split` : 'KITchen';
  const $ = s => document.querySelector(s);

  // Same per-object hue as scripts/build_samples.py (golden-ratio walk in HSV).
  function objColor(id) {
    const h = (id * 0.61803398875) % 1, s = 0.72, v = 1;
    const i = Math.floor(h * 6), f = h * 6 - i, p = v * (1 - s), q = v * (1 - f * s), t = v * (1 - (1 - f) * s);
    const [r, g, b] = [[v, t, p], [q, v, p], [p, v, t], [p, q, v], [t, p, v], [v, p, q]][i % 6];
    return `rgb(${Math.round(r * 255)},${Math.round(g * 255)},${Math.round(b * 255)})`;
  }

  const fetchJSON = url => fetch(url).then(r => { if (!r.ok) throw new Error(url + ' ' + r.status); return r.json(); });
  const ready = Promise.all([
    fetchJSON('data/stats.json'),
    fetchJSON('data/explorer_frames.json'),
    fetchJSON('static/models/models.json').catch(() => ({})),
  ]);

  /* ───────────── Theme ───────────── */
  const themeListeners = [];
  $('#theme-toggle').addEventListener('click', () => {
    const root = document.documentElement;
    const dark = root.dataset.theme ? root.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
    root.dataset.theme = dark ? 'light' : 'dark';
    try { localStorage.setItem('kitchen-theme', root.dataset.theme); } catch (e) {}
    themeListeners.forEach(f => f());
  });
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change', () => themeListeners.forEach(f => f()));

  /* ───────────── Copy buttons ───────────── */
  document.querySelectorAll('.copy').forEach(btn => btn.addEventListener('click', async () => {
    const text = document.getElementById(btn.dataset.copy).innerText;
    try { await navigator.clipboard.writeText(text); btn.textContent = 'Copied'; }
    catch (e) { btn.textContent = 'Press Ctrl+C'; }
    setTimeout(() => (btn.textContent = 'Copy'), 1600);
  }));

  ready.then(([stats, samples, models]) => {
    const classes = stats.classes.map(c => ({ ...c, category: CATS.includes(c.category) ? c.category : 'Other' }));
    const byId = Object.fromEntries(classes.map(c => [c.id, c]));
    initKpis(stats);
    initHero(samples);
    initExplorer(samples, byId, models);
    initObjects(classes, models);
    initCharts(stats, classes);
    // The sections above an anchor are drawn from data, so jump to it again once they are.
    if (location.hash) requestAnimationFrame(() => document.getElementById(location.hash.slice(1))?.scrollIntoView());
  }).catch(err => console.error('KITchen page data failed to load:', err));

  /* ───────────── KPIs ───────────── */
  function initKpis(stats) {
    const els = document.querySelectorAll('#kpis [data-k]');
    const run = () => els.forEach(el => {
      const target = stats.totals[el.dataset.k];
      if (target == null) return;
      const dec = String(target).includes('.') ? 1 : 0, t0 = performance.now(), dur = 1100;
      const tick = now => {
        const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
        el.textContent = (target * e).toLocaleString('en-US', { minimumFractionDigits: dec, maximumFractionDigits: dec });
        if (k < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    });
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) {
      els.forEach(el => { const v = stats.totals[el.dataset.k]; if (v != null) el.textContent = v.toLocaleString('en-US'); });
      return;
    }
    const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting)) { io.disconnect(); run(); } });
    io.observe($('#kpis'));
  }

  /* ───────────── Hero ───────────── */
  function initHero(samples) {
    const frames = samples.frames.filter(f => f.objects.some(o => o.pose));
    const a = $('#hero-a'), b = $('#hero-b'), cap = $('#hero-caption');
    let i = Math.max(0, frames.findIndex(f => f.stem === '016892')), showPose = false;
    const preload = k => { const f = frames[k % frames.length]; new Image().src = `static/samples/${f.stem}.jpg`; new Image().src = `static/samples/${f.stem}_pose.png`; };
    const set = () => {
      const f = frames[i];
      cap.textContent = `${splitName(f)} · ${f.objects.length} objects · ${showPose ? 'rendered 6D poses' : 'RGB'}`;
      b.classList.toggle('hidden', !showPose);
    };
    set();
    if (matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    setInterval(() => {
      if (document.hidden) return;
      if (showPose) {
        showPose = false; set();
        setTimeout(() => {
          i = (i + 1) % frames.length;
          a.src = `static/samples/${frames[i].stem}.jpg`;
          b.src = `static/samples/${frames[i].stem}_pose.png`;
          set();
        }, 900);
      } else { showPose = true; set(); preload(i + 1); }
    }, 3200);
  }

  /* ───────────── Explorer ───────────── */
  function initExplorer(samples, byId, models) {
    const cam = samples.camera, W = cam.w, H = cam.h;
    const stage = $('#stage'), svg = $('#st-svg'), tip = $('#st-tip'), list = $('#obj-list');
    const rgb = $('#st-rgb'), depth = $('#st-depth'), pose = $('#st-pose');
    const NS = 'http://www.w3.org/2000/svg';
    const layers = new Set(['masks']);
    let frame = null;

    const applyLayers = () => ['masks', 'boxes', 'pose', 'cuboids', 'labels'].forEach(l => stage.classList.toggle('show-' + l, layers.has(l)));
    applyLayers();
    document.querySelectorAll('#layer-toggles .chip').forEach(btn => btn.addEventListener('click', () => {
      const l = btn.dataset.layer;
      layers.has(l) ? layers.delete(l) : layers.add(l);
      btn.classList.toggle('on', layers.has(l)); btn.setAttribute('aria-pressed', layers.has(l));
      applyLayers();
    }));
    const blend = $('#depth-blend'), legend = $('#depth-legend');
    blend.addEventListener('input', () => {
      const v = blend.value / 100;
      depth.style.opacity = v; legend.style.opacity = v > 0.05 ? 1 : 0;
    });

    function project(X) { return [cam.fx * X[0] / X[2] + cam.cx, cam.fy * X[1] / X[2] + cam.cy]; }
    function cuboid(o) {
      const m = models[String(o.c)];
      if (!o.pose || !m) return null;
      const R = o.pose.R, t = o.pose.t, [x0, y0, z0] = m.min, [x1, y1, z1] = m.max;
      const P = [[x0, y0, z0], [x1, y0, z0], [x1, y1, z0], [x0, y1, z0], [x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1]].map(p => {
        const X = [0, 1, 2].map(r => R[r * 3] * p[0] + R[r * 3 + 1] * p[1] + R[r * 3 + 2] * p[2] + t[r]);
        return X[2] > 0.05 ? project(X) : null;
      });
      if (P.some(p => !p)) return null;
      const E = [[0, 1], [1, 2], [2, 3], [3, 0], [4, 5], [5, 6], [6, 7], [7, 4], [0, 4], [1, 5], [2, 6], [3, 7]];
      return E.map(([a, b]) => `M${P[a][0].toFixed(1)},${P[a][1].toFixed(1)}L${P[b][0].toFixed(1)},${P[b][1].toFixed(1)}`).join('');
    }
    const dist = o => o.pose ? Math.hypot(...o.pose.t) : null;

    function highlight(i) {
      svg.querySelectorAll('g.obj').forEach(g => {
        const on = i != null && +g.dataset.i === i;
        g.classList.toggle('hot', on); g.classList.toggle('dim', i != null && !on);
      });
      list.querySelectorAll('li').forEach(li => li.classList.toggle('hot', +li.dataset.i === i));
    }
    function showTip(o, evt) {
      const c = byId[o.c] || {}, d = dist(o);
      tip.innerHTML = `<b>${c.name || 'Class ' + o.c}</b><span class="t2">${c.category || ''}${d ? ` · ${d.toFixed(2)} m away` : ''}</span><br>` +
        `<span class="t2">${o.ok ? 'Confident label' : 'In ignore.json (uncertain)'}${o.pose ? ' · 6D pose' : ''}</span>`;
      const r = stage.getBoundingClientRect();
      let x = evt.clientX - r.left + 14, y = evt.clientY - r.top + 14;
      tip.classList.add('on');
      const tw = tip.offsetWidth, th = tip.offsetHeight;
      if (x + tw > r.width - 8) x = evt.clientX - r.left - tw - 14;
      if (y + th > r.height - 8) y = evt.clientY - r.top - th - 14;
      // Keep it inside the image (narrow screens leave no room on either side).
      x = Math.max(8, Math.min(x, r.width - tw - 8)); y = Math.max(8, Math.min(y, r.height - th - 8));
      tip.style.left = x + 'px'; tip.style.top = y + 'px';
    }
    const hideTip = () => tip.classList.remove('on');
    // On touch screens a tap pins the tooltip; tapping anywhere else clears it.
    document.addEventListener('pointerdown', e => {
      if (e.pointerType === 'touch' && !e.target.closest('#st-svg .m')) { highlight(null); hideTip(); }
    });
    // A finger that starts a scroll on the image should not leave a tooltip pinned.
    document.addEventListener('pointercancel', e => {
      if (e.target.closest && e.target.closest('#st-svg')) { highlight(null); hideTip(); }
    });

    function render(f) {
      frame = f;
      const base = `static/samples/${f.stem}`;
      rgb.src = base + '.jpg'; depth.src = base + '_depth.jpg'; pose.src = base + '_pose.png';
      $('#dl-near').textContent = (f.depth_range_mm[0] / 1000).toFixed(1) + ' m';
      $('#dl-far').textContent = (f.depth_range_mm[1] / 1000).toFixed(1) + ' m';
      svg.textContent = '';
      // Draw larger objects first so small ones stay hoverable on top.
      const order = f.objects.map((o, i) => i).sort((a, b) => f.objects[b].b[2] * f.objects[b].b[3] - f.objects[a].b[2] * f.objects[a].b[3]);
      const labelLayer = document.createElementNS(NS, 'g');
      for (const i of order) {
        const o = f.objects[i], col = objColor(o.c), c = byId[o.c] || {};
        const g = document.createElementNS(NS, 'g');
        g.setAttribute('class', 'obj'); g.dataset.i = i;
        const [cx, cy, w, h] = o.b, bx = (cx - w / 2) * W, by = (cy - h / 2) * H;
        let shape;
        if (o.p && o.p.length >= 6) {
          shape = document.createElementNS(NS, 'polygon');
          const pts = []; for (let k = 0; k < o.p.length; k += 2) pts.push(`${(o.p[k] * W).toFixed(1)},${(o.p[k + 1] * H).toFixed(1)}`);
          shape.setAttribute('points', pts.join(' '));
        } else {
          shape = document.createElementNS(NS, 'rect');
          Object.entries({ x: bx, y: by, width: w * W, height: h * H }).forEach(([k, v]) => shape.setAttribute(k, v));
        }
        shape.setAttribute('class', 'm' + (o.ok ? '' : ' unsure'));
        shape.setAttribute('fill', col); shape.setAttribute('stroke', col);
        g.appendChild(shape);
        const box = document.createElementNS(NS, 'rect');
        Object.entries({ x: bx, y: by, width: w * W, height: h * H, class: 'b', stroke: col }).forEach(([k, v]) => box.setAttribute(k, v));
        g.appendChild(box);
        const cub = cuboid(o);
        if (cub) { const p = document.createElementNS(NS, 'path'); p.setAttribute('d', cub); p.setAttribute('class', 'cub'); p.setAttribute('stroke', col); g.appendChild(p); }
        svg.appendChild(g);
        // label
        const lg = document.createElementNS(NS, 'g'); lg.setAttribute('class', 'lbl'); lg.dataset.i = i;
        const txt = document.createElementNS(NS, 'text'); txt.textContent = c.name || o.c;
        txt.setAttribute('x', bx + 6); txt.setAttribute('y', Math.max(22, by - 7));
        const rect = document.createElementNS(NS, 'rect');
        rect.setAttribute('x', bx); rect.setAttribute('y', Math.max(0, by - 29)); rect.setAttribute('height', 28);
        rect.setAttribute('width', (c.name || '').length * 11 + 14); rect.setAttribute('rx', 4);
        lg.appendChild(rect); lg.appendChild(txt);
        const wrap = document.createElementNS(NS, 'g'); wrap.setAttribute('class', 'obj'); wrap.dataset.i = i; wrap.appendChild(lg);
        labelLayer.appendChild(wrap);
        shape.addEventListener('pointermove', e => { highlight(i); showTip(o, e); });
        shape.addEventListener('pointerdown', e => { highlight(i); showTip(o, e); });
        shape.addEventListener('pointerleave', e => { if (e.pointerType !== 'touch') { highlight(null); hideTip(); } });
      }
      svg.appendChild(labelLayer);

      // Panel
      const nPose = f.objects.filter(o => o.pose).length, nOk = f.objects.filter(o => o.ok).length;
      $('#fr-title').textContent = splitName(f);
      $('#fr-sub').textContent = `${f.objects.length} annotated objects · 1920×1080`;
      $('#fr-stats').innerHTML = `<div><b>${f.objects.length}</b><span>objects</span></div><div><b>${nPose}</b><span>6D poses</span></div><div><b>${nOk}</b><span>confident</span></div>`;
      $('#fr-count').textContent = '';
      list.textContent = '';
      f.objects.map((o, i) => ({ o, i, d: dist(o) })).sort((a, b) => (a.d ?? 99) - (b.d ?? 99)).forEach(({ o, i, d }) => {
        const li = document.createElement('li'); li.dataset.i = i; li.tabIndex = 0;
        const c = byId[o.c] || {};
        li.innerHTML = `<i class="sw" style="background:${objColor(o.c)}"></i><span class="nm">${c.name || o.c}</span>` +
          (o.ok ? '' : '<span class="q" title="Listed in ignore.json">uncertain</span>') +
          `<span class="d">${d ? d.toFixed(2) + ' m' : '–'}</span>`;
        li.addEventListener('pointerenter', () => highlight(i));
        li.addEventListener('pointerleave', () => highlight(null));
        li.addEventListener('focus', () => highlight(i));
        li.addEventListener('blur', () => highlight(null));
        list.appendChild(li);
      });
      document.querySelectorAll('#filmstrip .thumb').forEach(t => { const on = t.dataset.stem === f.stem; t.classList.toggle('on', on); t.setAttribute('aria-selected', on); });
    }

    const strip = $('#filmstrip');
    samples.frames.forEach(f => {
      const b = document.createElement('button');
      b.type = 'button'; b.className = 'thumb'; b.dataset.stem = f.stem; b.setAttribute('role', 'option');
      b.setAttribute('aria-label', `${splitName(f)}, ${f.objects.length} objects`);
      b.innerHTML = `<img loading="lazy" src="static/samples/${f.stem}_t.jpg" alt=""><span>${f.objects.length} objects</span>`;
      b.addEventListener('click', () => render(f));
      strip.appendChild(b);
    });
    stage.addEventListener('keydown', e => {
      const i = samples.frames.indexOf(frame);
      if (e.key === 'ArrowRight') render(samples.frames[(i + 1) % samples.frames.length]);
      if (e.key === 'ArrowLeft') render(samples.frames[(i - 1 + samples.frames.length) % samples.frames.length]);
    });
    stage.tabIndex = 0;
    render(samples.frames.find(f => f.stem === '016892') || samples.frames[0]);
  }

  /* ───────────── Object library ───────────── */
  function initObjects(classes, models) {
    const items = classes.filter(c => c.id > 0 && c.instances >= 100 && models[String(c.id)]);
    $('#lib-count').textContent = items.length;
    const more = $('#obj-more'); let expanded = false;
    more.addEventListener('click', () => { expanded = !expanded; draw(); });
    const grid = $('#obj-grid'), search = $('#obj-search'), sort = $('#obj-sort'), filters = $('#cat-filters');
    let cat = 'All';
    const cats = ['All', ...CATS.filter(c => items.some(i => i.category === c))];
    const drawChips = () => {
      filters.innerHTML = cats.map(c => {
        const n = c === 'All' ? items.length : items.filter(i => i.category === c).length;
        return `<button type="button" class="chip${c === cat ? ' on' : ''}" data-c="${c}" aria-pressed="${c === cat}">` +
          (c === 'All' ? '' : `<i class="sw" style="background:${catColor(c)}"></i>`) + `${c} <span class="muted">${n}</span></button>`;
      }).join('');
      filters.querySelectorAll('.chip').forEach(b => b.addEventListener('click', () => { cat = b.dataset.c; drawChips(); draw(); }));
    };
    const draw = () => {
      const q = search.value.trim().toLowerCase();
      let list = items.filter(i => (cat === 'All' || i.category === cat) && (!q || i.name.toLowerCase().includes(q) || i.key.toLowerCase().includes(q)));
      const key = sort.value;
      list.sort((a, b) => key === 'name' ? a.name.localeCompare(b.name) : key === 'dist' ? (a.median_dist_cm ?? 1e9) - (b.median_dist_cm ?? 1e9) : b.instances - a.instances);
      const total = list.length, limited = !expanded && !q && total > 21;
      if (limited) list = list.slice(0, 21);
      more.parentElement.hidden = !(total > 21) || !!q;
      more.textContent = expanded ? 'Show fewer' : `Show all ${total} objects`;
      grid.innerHTML = list.length ? list.map(i => `
        <button type="button" class="obj-card" data-id="${i.id}" aria-label="${i.name}, open 3D view">
          <img loading="lazy" src="static/models/thumbs/obj_${pad6(i.id)}.webp" alt="" width="320" height="320">
          <span class="nm">${i.name}</span>
          <span class="meta"><span class="cat"><i style="background:${catColor(i.category)}"></i>${i.category}</span><span class="n">${compact(i.instances)}</span></span>
        </button>`).join('') : '<p class="empty">No objects match.</p>';
      grid.querySelectorAll('.obj-card').forEach(b => b.addEventListener('click', () => open(+b.dataset.id)));
    };
    const modal = $('#obj-modal'), viewer = $('#om-viewer');
    let mvRequested = false;
    function open(id) {
      const c = items.find(i => i.id === id), m = models[String(id)];
      if (!mvRequested && !customElements.get('model-viewer')) {
        // Load the 3D viewer only when someone first opens a model.
        mvRequested = true;
        const s = document.createElement('script');
        s.type = 'module'; s.src = 'https://cdn.jsdelivr.net/npm/@google/model-viewer@3.5.0/dist/model-viewer.min.js';
        document.head.appendChild(s);
      }
      // Show the thumbnail until the model has loaded (and before the viewer script arrives).
      const src = `static/models/obj_${pad6(id)}.glb`;
      if (viewer.getAttribute('src') !== src || !viewer.loaded) viewer.style.setProperty('--om-thumb', `url(${new URL(`static/models/thumbs/obj_${pad6(id)}.webp`, location.href)})`);
      // Attributes (not properties), so they apply once the element upgrades.
      viewer.setAttribute('src', src);
      $('#om-cat').textContent = c.category;
      $('#om-title').textContent = c.name;
      $('#om-id').textContent = `obj_${pad6(id)} · class ${id} · "${c.key}"`;
      const size = m ? m.max.map((v, k) => Math.round((v - m.min[k]) * 100)).join(' × ') + ' cm' : '–';
      $('#om-stats').innerHTML = [
        ['2D instances', fmt(c.instances)],
        ['6D poses', fmt(c.poses)], ['Median distance', c.median_dist_cm ? (c.median_dist_cm / 100).toFixed(2) + ' m' : '–'],
        ['Confident labels', c.instances ? (100 * c.confident / c.instances).toFixed(1) + '%' : '–'], ['Size', size],
      ].map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('');
      modal.showModal();
    }
    viewer.addEventListener('load', () => viewer.style.removeProperty('--om-thumb'));
    $('#om-close').addEventListener('click', () => modal.close());
    modal.addEventListener('click', e => { if (e.target === modal) modal.close(); });
    search.addEventListener('input', draw); sort.addEventListener('change', draw);
    themeListeners.push(() => { drawChips(); draw(); });
    drawChips(); draw();
  }

  /* ───────────── Charts ───────────── */
  function initCharts(stats, classes) {
    if (!window.d3) { console.warn('d3 not loaded; charts skipped'); return; }
    const d3 = window.d3;
    const shown = classes.filter(c => c.id > 0 && c.instances >= 100);
    $('#cls-count').textContent = shown.length;
    $('#stats-generated').textContent = `Updated ${stats.generated}.`;

    // Category legend
    const legend = () => {
      $('#cat-legend').innerHTML = CATS.map(c => `<span><i style="background:${catColor(c)}"></i>${c} <span class="muted">${shown.filter(s => s.category === c).length}</span></span>`).join('');
    };

    // Shared tooltip per chart container
    function tooltip(el, onClear) {
      let t = el.querySelector('.ctip');
      if (!t) { t = document.createElement('div'); t.className = 'ctip'; el.appendChild(t); }
      el._onClear = onClear;
      if (!el.dataset.tapHide) {
        el.dataset.tapHide = '1';
        const clear = () => {
          el.querySelector('.ctip')?.classList.remove('on'); el.classList.remove('hovering');
          el.querySelectorAll('.bar.on').forEach(n => n.classList.remove('on'));
          el._onClear?.();
        };
        document.addEventListener('pointerdown', e => { if (e.pointerType === 'touch' && !(el.contains(e.target) && e.target.closest('.hit, canvas'))) clear(); });
        // A finger that starts a scroll on the chart should not leave a tooltip pinned.
        document.addEventListener('pointercancel', e => { if (el.contains(e.target)) clear(); });
      }
      return {
        show(html, x, y) {
          t.innerHTML = html; t.classList.add('on');
          const w = t.offsetWidth, cw = el.clientWidth;
          t.style.left = Math.max(0, Math.min(cw - w, x - w / 2)) + 'px';
          t.style.top = (y - t.offsetHeight - 12) + 'px';
        },
        hide() { t.classList.remove('on'); },
      };
    }
    // Bar with a 4px rounded data end, square at the baseline.
    function barPath(x, y, w, h, r = 4) {
      if (h <= 0) return '';
      r = Math.min(r, w / 2, h);
      return `M${x},${y + h}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h}Z`;
    }
    function frameSvg(el, height, m) {
      el.querySelector('svg')?.remove();
      const width = el.clientWidth;
      const svg = d3.select(el).append('svg').attr('viewBox', `0 0 ${width} ${height}`).attr('height', height);
      return { svg, width, height, iw: width - m.l - m.r, ih: height - m.t - m.b, g: svg.append('g').attr('transform', `translate(${m.l},${m.t})`) };
    }
    const yAxis = (g, y, iw, f = compact) => {
      g.append('g').attr('class', 'grid').call(d3.axisLeft(y).ticks(4).tickSize(-iw).tickFormat(''));
      g.append('g').attr('class', 'axis').call(d3.axisLeft(y).ticks(4).tickFormat(f).tickSizeOuter(0)).call(a => a.select('.domain').remove());
    };

    let metric = 'instances';
    function drawClasses() {
      const el = $('#chart-classes');
      const data = shown.slice().sort((a, b) => b[metric] - a[metric]);
      const m = { t: 10, r: 8, b: 30, l: 46 };
      const { g, iw, ih } = frameSvg(el, 300, m);
      const x = d3.scaleBand().domain(data.map(d => d.id)).range([0, iw]).paddingInner(0.18);
      const y = d3.scaleLinear().domain([0, d3.max(data, d => d[metric])]).nice().range([ih, 0]);
      yAxis(g, y, iw);
      g.append('line').attr('x1', 0).attr('x2', iw).attr('y1', ih).attr('y2', ih).attr('stroke', css('--border-strong'));
      const bars = g.selectAll('.bar').data(data).join('path').attr('class', 'bar')
        .attr('fill', d => catColor(d.category))
        .attr('d', d => barPath(x(d.id), y(d[metric]), x.bandwidth(), ih - y(d[metric]), Math.min(4, x.bandwidth() / 2)));
      g.append('text').attr('class', 'axis-note').attr('x', 0).attr('y', ih + 20).attr('fill', css('--text-3')).attr('font-size', 11).text('← most annotated');
      g.append('text').attr('x', iw).attr('y', ih + 20).attr('text-anchor', 'end').attr('fill', css('--text-3')).attr('font-size', 11).text('least annotated →');
      // Direct label for the top class.
      const top = data[0];
      g.append('text').attr('class', 'ann').attr('x', x(top.id) + x.bandwidth() + 6).attr('y', y(top[metric]) + 10).text(`${top.name} · ${compact(top[metric])}`);
      const tt = tooltip(el);
      g.selectAll('.hit').data(data).join('rect').attr('class', 'hit')
        .attr('x', d => x(d.id) - x.step() * x.paddingInner() / 2).attr('width', x.step()).attr('y', 0).attr('height', ih)
        .on('pointerenter pointermove pointerdown', (e, d) => {
          el.classList.add('hovering'); bars.classed('on', b => b === d);
          tt.show(`<b>${d.name}</b> <span class="k">· ${d.category}</span><br>${fmt(d.instances)} instances · ${fmt(d.poses)} poses${d.median_dist_cm ? `<br><span class="k">median distance ${(d.median_dist_cm / 100).toFixed(2)} m</span>` : ''}`,
            m.l + x(d.id) + x.bandwidth() / 2, m.t + y(d[metric]));
        })
        .on('pointerleave', e => { if (e.pointerType !== 'touch') { el.classList.remove('hovering'); bars.classed('on', false); tt.hide(); } });
    }
    document.querySelectorAll('#cls-metric .chip').forEach(b => b.addEventListener('click', () => {
      metric = b.dataset.m;
      document.querySelectorAll('#cls-metric .chip').forEach(c => { c.classList.toggle('on', c === b); c.setAttribute('aria-pressed', c === b); });
      drawClasses();
    }));

    function histogram(el, values, { labels, xTitle, color, height = 230, tipFmt, marker, yFmt, tickEvery, lastTick }) {
      const m = { t: 14, r: 8, b: 40, l: 46 };
      const { g, iw, ih } = frameSvg(el, height, m);
      const idx = values.map((_, i) => i);
      const x = d3.scaleBand().domain(idx).range([0, iw]).paddingInner(values.length > 30 ? 0.12 : 0.2);
      const y = d3.scaleLinear().domain([0, d3.max(values)]).nice().range([ih, 0]);
      yAxis(g, y, iw, yFmt);
      // Label about 8 bins, fewer on narrow screens; optionally always label the last (overflow) bin.
      const every = tickEvery || Math.ceil(values.length / (iw < 420 ? 4 : 8));
      const ticks = idx.filter(i => i % every === 0 && !(lastTick && i < values.length - 1 && values.length - 1 - i < every / 2));
      if (lastTick && ticks[ticks.length - 1] !== values.length - 1) ticks.push(values.length - 1);
      g.append('g').attr('class', 'axis').attr('transform', `translate(0,${ih})`)
        .call(d3.axisBottom(x).tickValues(ticks).tickFormat(i => labels[i]).tickSizeOuter(0));
      g.append('text').attr('x', iw / 2).attr('y', ih + 34).attr('text-anchor', 'middle').attr('fill', css('--text-3')).attr('font-size', 11).text(xTitle);
      const bars = g.selectAll('.bar').data(values).join('path').attr('class', 'bar').attr('fill', color)
        .attr('d', (v, i) => barPath(x(i), y(v), x.bandwidth(), ih - y(v), Math.min(4, x.bandwidth() / 2)));
      if (marker != null) {
        const mx = x(marker) + x.bandwidth() / 2;
        g.append('line').attr('class', 'ann-line').attr('x1', mx).attr('x2', mx).attr('y1', 0).attr('y2', ih);
        g.append('text').attr('class', 'ann').attr('x', mx + 5).attr('y', 10).text('median');
      }
      const tt = tooltip(el);
      g.selectAll('.hit').data(idx).join('rect').attr('class', 'hit')
        .attr('x', i => x(i) - x.step() * x.paddingInner() / 2).attr('width', x.step()).attr('y', 0).attr('height', ih)
        .on('pointerenter pointermove pointerdown', (e, i) => {
          el.classList.add('hovering'); bars.classed('on', (_, k) => k === i);
          tt.show(tipFmt(i, values[i]), m.l + x(i) + x.bandwidth() / 2, m.t + y(values[i]));
        })
        .on('pointerleave', e => { if (e.pointerType !== 'touch') { el.classList.remove('hovering'); bars.classed('on', false); tt.hide(); } });
    }
    const medianIndex = arr => { const tot = d3.sum(arr); let acc = 0; for (let i = 0; i < arr.length; i++) { acc += arr[i]; if (acc >= tot / 2) return i; } return 0; };

    function drawOpf() {
      // Shares of images holding k objects; everything from 70 up goes in one "70+" bin.
      const all = stats.objects_per_frame, cap = 70;
      const v = [...all.slice(0, cap), d3.sum(all.slice(cap))];
      const med = medianIndex(all);
      $('#opf-median').textContent = med;
      const lab = i => i === cap ? `${cap}+` : String(i);
      histogram($('#chart-opf'), v.map(s => 100 * s), {
        labels: v.map((_, i) => lab(i)), xTitle: 'objects in the image', color: css('--s1'), marker: Math.min(med, cap), tickEvery: 10,
        tipFmt: (i, p) => `<b>${lab(i)} objects</b><br>${p.toFixed(1)}% of images`, yFmt: d => d + '%',
      });
    }
    function drawDist() {
      const v = stats.distance_hist, bw = stats.distance_bin_cm, tot = d3.sum(v);
      histogram($('#chart-dist'), v, {
        labels: v.map((_, i) => i === v.length - 1 ? `${(i * bw / 100).toFixed(1)}+` : (i * bw / 100).toFixed(1)), xTitle: 'distance from camera (m)', color: css('--s3'), marker: medianIndex(v), lastTick: true,
        tipFmt: (i, n) => `<b>${(i * bw / 100).toFixed(1)}–${i === v.length - 1 ? '∞' : ((i + 1) * bw / 100).toFixed(1)} m</b><br>${fmt(n)} poses <span class="k">(${(100 * n / tot).toFixed(1)}%)</span>`,
      });
    }
    function drawArea() {
      const b = stats.box_area_bins, v = stats.box_area_hist, tot = d3.sum(v);
      const pct = x => String(+(x * 100).toFixed(2));
      const labels = v.map((_, i) => i === 0 ? `<${pct(b[1])}` : i === v.length - 1 ? `>${pct(b[i])}` : `${pct(b[i])}–${pct(b[i + 1])}`);
      histogram($('#chart-area'), v, {
        labels, xTitle: 'box area, % of the image', color: css('--s2'),
        tipFmt: (i, n) => `<b>${labels[i]}%</b> of the image<br>${fmt(n)} objects <span class="k">(${(100 * n / tot).toFixed(1)}%)</span>`,
      });
    }
    function drawHeat() {
      const el = $('#chart-heat'), { w, h, cells } = stats.center_heatmap;
      el.textContent = '';
      const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
      cv.style.aspectRatio = `${w} / ${h}`;
      const ctx = cv.getContext('2d'), max = d3.quantile(cells.flat().sort(d3.ascending), 0.99);
      const ramp = d3.interpolateRgbBasis(['--q0', '--q1', '--q2', '--q3', '--q4', '--q5'].map(css));
      const img = ctx.createImageData(w, h);
      cells.forEach((row, yy) => row.forEach((v, xx) => {
        const c = d3.rgb(ramp(Math.pow(Math.min(1, v / max), 1.6))), k = (yy * w + xx) * 4;
        img.data[k] = c.r; img.data[k + 1] = c.g; img.data[k + 2] = c.b; img.data[k + 3] = 255;
      }));
      ctx.putImageData(img, 0, 0);
      cv.setAttribute('role', 'img'); cv.setAttribute('aria-label', 'Heat map of where object centres fall in the image; densest in the lower middle.');
      el.appendChild(cv);
      const sc = document.createElement('div'); sc.className = 'heat-scale'; sc.innerHTML = '<span>fewer</span><i></i><span>more objects</span>';
      el.appendChild(sc);
      const tt = tooltip(el), tot = d3.sum(cells.flat());
      const heatTip = e => {
        const r = cv.getBoundingClientRect(), xx = Math.floor((e.clientX - r.left) / r.width * w), yy = Math.floor((e.clientY - r.top) / r.height * h);
        if (xx < 0 || yy < 0 || xx >= w || yy >= h) return;
        tt.show(`${fmt(cells[yy][xx])} objects <span class="k">(${(100 * cells[yy][xx] / tot).toFixed(2)}%)</span>`, e.clientX - el.getBoundingClientRect().left, e.clientY - el.getBoundingClientRect().top);
      };
      cv.addEventListener('pointermove', heatTip); cv.addEventListener('pointerdown', heatTip);
      cv.addEventListener('pointerleave', e => { if (e.pointerType !== 'touch') tt.hide(); });
    }
    function drawTimeline() {
      const el = $('#chart-timeline'), raw = stats.timeline.values;
      const vals = raw.map((_, i) => { const w = raw.slice(Math.max(0, i - 2), i + 3); return +(w.reduce((a, b) => a + b, 0) / w.length).toFixed(1); });
      const m = { t: 24, r: 8, b: 26, l: 46 };
      const { g, iw, ih } = frameSvg(el, 224, m);
      const x = d3.scaleLinear().domain([0, vals.length - 1]).range([0, iw]);
      const y = d3.scaleLinear().domain([0, d3.max(vals)]).nice().range([ih, 0]);
      yAxis(g, y, iw, d3.format('d'));
      // Benchmark split of every frame (lab room = train, kitchen setups = val/test), as a strip above the plot
      const bands = stats.benchmark.bands, xf = f => x(f * (vals.length - 1));
      g.append('g').selectAll('rect').data(bands).join('rect')
        .attr('x', d => xf(d[0])).attr('width', d => Math.max(0.6, xf(d[1]) - xf(d[0]))).attr('y', -18).attr('height', 10)
        .attr('fill', d => css(SPLITS[d[2]][1]));
      $('#split-legend').innerHTML = Object.values(SPLITS).map(([n, c]) => `<span><i style="background:${css(c)}"></i>${n}</span>`).join('');
      const accent = css('--accent');
      g.append('path').datum(vals).attr('fill', accent).attr('fill-opacity', 0.14)
        .attr('d', d3.area().x((d, i) => x(i)).y0(ih).y1(d => y(d)).curve(d3.curveMonotoneX));
      g.append('path').datum(vals).attr('fill', 'none').attr('stroke', accent).attr('stroke-width', 2)
        .attr('d', d3.line().x((d, i) => x(i)).y(d => y(d)).curve(d3.curveMonotoneX));
      g.append('g').attr('class', 'axis').attr('transform', `translate(0,${ih})`)
        .call(d3.axisBottom(x).ticks(0).tickSizeOuter(0));
      const cross = g.append('line').attr('y1', 0).attr('y2', ih).attr('stroke', css('--text-3')).attr('opacity', 0);
      const dot = g.append('circle').attr('r', 4.5).attr('fill', accent).attr('stroke', css('--surface')).attr('stroke-width', 2).attr('opacity', 0);
      const tt = tooltip(el, () => { cross.attr('opacity', 0); dot.attr('opacity', 0); });
      g.append('rect').attr('class', 'hit').attr('width', iw).attr('height', ih)
        .on('pointermove pointerdown', e => {
          const xi = x.invert(d3.pointer(e)[0]), i = Math.max(0, Math.min(vals.length - 1, Math.round(xi)));
          cross.attr('x1', x(i)).attr('x2', x(i)).attr('opacity', 1); dot.attr('cx', x(i)).attr('cy', y(vals[i])).attr('opacity', 1);
          // Name the split under the cursor, so the tooltip agrees with the strip.
          const fi = xi / (vals.length - 1), band = bands.find(d => fi >= d[0] && fi < d[1]) || bands[bands.length - 1];
          tt.show(`<b>${vals[i]} objects per image</b>${band ? `<br><span class="k">${SPLITS[band[2]][0]}</span>` : ''}`, m.l + x(i), m.t + y(vals[i]));
        })
        .on('pointerleave', e => { if (e.pointerType !== 'touch') { cross.attr('opacity', 0); dot.attr('opacity', 0); tt.hide(); } });
    }
    function drawTable() {
      const tb = $('#seq-table tbody'), tf = $('#seq-table tfoot'), T = stats.totals;
      const pct = (a, b) => `<span class="pct">${(100 * a / b).toFixed(1)}%</span>`;
      tb.innerHTML = stats.benchmark.splits.map(s => `<tr${s.id === 'buffer' ? ' class="muted-row"' : ''}><td><span class="sw" style="background:${css(SPLITS[s.id][1])}"></span>` +
        `${s.id === 'buffer' ? 'Unassigned <span class="tag">not used</span>' : `<b>${s.name}</b>`}</td>` +
        `<td class="num">${fmt(s.objects)}</td><td class="num">${fmt(s.confident)}${pct(s.confident, s.objects)}</td><td class="num">${fmt(s.poses)}</td></tr>`).join('');
      tf.innerHTML = `<tr><td>Total</td><td class="num">${fmt(T.objects)}</td><td class="num">${fmt(T.confident)}${pct(T.confident, T.objects)}</td><td class="num">${fmt(T.poses)}</td></tr>`;
    }

    const drawAll = () => { legend(); drawClasses(); drawOpf(); drawDist(); drawArea(); drawHeat(); drawTimeline(); drawTable(); };
    drawAll();
    themeListeners.push(drawAll);
    let rt; window.addEventListener('resize', () => { clearTimeout(rt); rt = setTimeout(drawAll, 150); });
  }
})();
